export const pages = {"index": "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Route 66 Hemp Has Closed</title>\n<meta name=\"description\" content=\"Route 66 Hemp ended retail operations on November 11, 2026. Thank you to our St. Robert customers and community.\">\n<link rel=\"canonical\" href=\"https://www.route66hemp.com/\">\n<meta property=\"og:title\" content=\"Route 66 Hemp Has Closed\"><meta property=\"og:description\" content=\"Our final day of business was November 11, 2026. Thank you for your support.\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://www.route66hemp.com/\">\n\n<style>\n*{box-sizing:border-box}body{margin:0;background:#f5f6f1;color:#183429;font:18px/1.65 system-ui,-apple-system,sans-serif}main{max-width:720px;margin:auto;padding:64px 24px}article{background:#fff;border:1px solid #dbe4da;border-radius:20px;padding:40px;box-shadow:0 12px 40px #16352508}img{display:block;width:112px;height:112px;object-fit:contain;margin-bottom:28px}h1{font-size:clamp(30px,6vw,44px);line-height:1.15;letter-spacing:-.035em;margin:0 0 28px}p{margin:0 0 22px}a{color:#145c42;text-underline-offset:4px;overflow-wrap:anywhere}a:focus-visible{outline:3px solid #145c42;outline-offset:4px}footer{font-size:14px;margin-top:28px;display:flex;flex-wrap:wrap;gap:16px}@media(max-width:480px){main{padding:28px 16px}article{padding:28px 22px}}\n</style>\n</head><body><main><article>\n<img src=\"data:image/png;base64,\" alt=\"Route 66 Hemp\" width=\"112\" height=\"112\">\n<h1>Route 66 Hemp Has Closed</h1>\n<p>Route 66 Hemp ended retail operations on <strong>November 11, 2026</strong>.</p>\n<p>We closed in response to changes in Missouri hemp regulations.</p>\n<p>Thank you to everyone who supported our store in St. Robert. We appreciate our customers and community.</p>\n<p>We are no longer accepting orders.</p>\n<!-- CONTACT: Build requires an explicitly confirmed email. -->\n<p>For questions about a previous purchase or other business matters, please contact <a href=\"mailto:route66hemp@gmail.com\">route66hemp@gmail.com</a>.</p>\n<footer><a href=\"/privacy-policy/\">Privacy policy</a><a href=\"/terms-of-service/\">Terms of service</a><a href=\"/cookie-policy/\">Cookie policy</a></footer>\n</article></main></body></html>\n", "privacy-policy": "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Privacy Policy - Route 66 Hemp</title><style>body{max-width:900px;margin:auto;padding:28px;font:17px/1.65 system-ui;color:#183429}a{color:#145c42}table{display:block;overflow:auto}h1{line-height:1.2}</style></head><body><a href=\"/\">Back to closure notice</a><p>Archived policy retained for reference following the store closure. The closure page does not load the former site's analytics scripts.</p><main>\n          <!-- Auto-generated Table of Contents -->\n          <details id=\"toc\" class=\"toc\">\n            <summary aria-controls=\"toc-list\" aria-expanded=\"false\">On this page</summary>\n            <ul id=\"toc-list\"><!-- populated by JS --></ul>\n          </details>\n    \n          <!-- Main policy content -->\n          <article class=\"prose\" id=\"policy\">\n            <section id=\"intro\">\n              <p>We are Route 66 Hemp LLC. This privacy policy explains how we collect, use, and protect your personal information when you use our services.</p>\n              <div class=\"note\" role=\"note\" aria-label=\"Contact\">\n                <strong>Contact</strong>\n                <address>\n                  14076 State Hwy Z, St Robert, MO 65584, United States<br/>\n                  Email: <a href=\"mailto:route66hemp@gmail.com\">route66hemp@gmail.com</a><br/>\n                  Phone: <a href=\"tel:+15736776418\">(573) 677-6418</a>\n                </address>\n              </div>\n            </section>\n    \n            <!-- Keep your clear heading hierarchy; the JS below will anchor & index them -->\n            <h2 id=\"what-is-this-policy\">Introduction</h2>\n            <p><strong>What is this policy about?</strong> This document explains how this website collects, uses, and protects your personal data to achieve the purposes outlined here.</p>\n            <p><strong>What is personal data?</strong> Personal data refers to information that can identify you directly or indirectly (e.g., name, email address, cookies/trackers, usage and device data).</p>\n    \n            <h2 id=\"types-of-data\">Types of data collected</h2>\n            <ul>\n              <li>First name</li>\n              <li>Last name</li>\n              <li>Email address</li>\n              <li>Trackers</li>\n              <li>Usage data</li>\n            </ul>\n            <p>Unless stated otherwise, requested data is mandatory to provide the service. When data is optional, you may decline without impacting core functionality.</p>\n    \n            <h2 id=\"processing\">Mode and place of processing personal data</h2>\n            <h3>Methods of processing</h3>\n            <p>We use appropriate technical and organizational measures to protect your data and process it only for stated purposes.</p>\n            <h3>Place</h3>\n            <p>Data may be processed at our offices and by service providers in other locations (including outside your country, where applicable).</p>\n            <h3>Retention time</h3>\n            <p>We keep personal data as long as necessary for the purposes collected and longer where required by law or with your consent.</p>\n    \n            <h2 id=\"detailed-processing\">Detailed information on processing</h2>\n            <h3 id=\"analytics\">Analytics</h3>\n            <h4>Google Analytics (Universal Analytics) \u2013 Google LLC</h4>\n            <p>Used to measure traffic and usage. See Google\u2019s <a href=\"https://policies.google.com/technologies/partner-sites\">Partner Policy</a> and <a href=\"https://business.safety.google/privacy/\">Business Data</a>. Opt-out via the <a href=\"https://tools.google.com/dlpage/gaoptout\">GA Opt-out Add-on</a>.</p>\n    \n            <h3 id=\"external-content\">Displaying content from external platforms</h3>\n            <h4>Google Fonts \u2013 Google LLC</h4>\n            <p>Typeface delivery; may collect usage data. See links above.</p>\n    \n            <h2 id=\"contacting\">Contacting you</h2>\n            <h3>Contact form</h3>\n            <p>By submitting the form, you allow us to use your details to reply to your request (personal data: first name, last name, email).</p>\n    \n            <h2 id=\"legal-basis\">Legal basis of processing</h2>\n            <ul>\n              <li>Consent</li>\n              <li>Contract performance or pre-contractual steps</li>\n              <li>Legal obligation</li>\n              <li>Legitimate interests</li>\n            </ul>\n    \n            <h2 id=\"gdpr-rights\">Your rights (GDPR)</h2>\n            <ul>\n              <li>Withdraw consent</li>\n              <li>Object to processing</li>\n              <li>Access, rectify, restrict, delete</li>\n              <li>Portability</li>\n              <li>Lodge a complaint</li>\n            </ul>\n            <hr>\n            <section id=\"california\">\n              <h2>Further information for California residents</h2>\n            \n              <h3>About this section</h3>\n              <p>This section supplements the rest of our Privacy Policy. It is provided by the business operating this website and, where applicable, its parent, subsidiaries, and affiliates (collectively, \u201cwe,\u201d \u201cus,\u201d or \u201cour\u201d).</p>\n            \n              <h4>Applicability</h4>\n              <p>This section applies to consumers residing in California under the California Consumer Privacy Act of 2018 (\u201cCCPA\u201d), as amended by the California Privacy Rights Act (\u201cCPRA\u201d) and related regulations. For these consumers, this section controls if it conflicts with other parts of the policy.</p>\n            \n              <h4>Definition</h4>\n              <p>\u201cPersonal information\u201d has the meaning given in the CCPA/CPRA.</p>\n            \n              <h3>Categories of personal information we collect</h3>\n              <ul>\n                <li>We have collected the following categories of personal information:\n                  <ul>\n                    <li>Identifiers</li>\n                    <li>Internet or other electronic network activity information</li>\n                  </ul>\n                </li>\n                <li>We do not collect sensitive personal information.</li>\n                <li>We will not collect additional categories without notice.</li>\n              </ul>\n            \n              <h3>Purposes for using personal information</h3>\n              <p><strong>Business purposes.</strong> We use personal information to operate this website and its features. Processing is necessary and proportionate to the purposes for which the information was collected and limited to compatible operational uses.</p>\n              <p><strong>Commercial/legal purposes.</strong> We may also use personal information for other commercial reasons, to comply with law, and to protect our rights and interests, including before competent authorities.</p>\n              <p><strong>No incompatible use.</strong> We will not process personal information for unexpected or incompatible purposes without your consent.</p>\n            \n              <h3>Retention</h3>\n              <p>Unless otherwise stated in <em>Detailed information on the processing of personal data</em>, we retain personal information only as long as reasonably necessary for the purposes for which it was collected (or longer if required by law).</p>\n            \n              <h3>Sources of personal information</h3>\n              <p>We collect personal information directly and indirectly from you when you use this website.</p>\n              <p><strong>Direct collection:</strong> e.g., when you submit a form.</p>\n              <p><strong>Indirect collection:</strong> e.g., through your site navigation; certain data is observed/collected automatically.</p>\n              <p><strong>Third parties:</strong> we may receive personal information from service providers and partners supporting the website and its features.</p>\n            \n              <h3>How we disclose, sell, or share information</h3>\n              <p><strong>Disclosure for business purposes.</strong> We may disclose personal information to third parties (not including \u201cservice providers\u201d or \u201ccontractors\u201d as defined by the CCPA) as listed in <em>Detailed information on the processing of personal data</em>. Those third parties are grouped by processing purpose.</p>\n              <p><strong>Sale or sharing.</strong> \u201cSale\u201d means providing personal information to a third party for monetary or other valuable consideration. \u201cSharing\u201d means providing personal information to a third party for cross-context behavioral advertising (whether or not consideration is exchanged). Transfers to service providers under a compliant written contract are not \u201csales\u201d or \u201csharing.\u201d</p>\n            \n              <h3>Opt-out rights</h3>\n              <p>We may sell or share your personal information as described above. You have the right to opt out at any time. You can contact us using the details at the start of this document or use the privacy choices link on this website. We honor user-enabled Global Privacy Control (GPC) signals. We will use any information provided with an opt-out request solely to comply with that request and will wait at least 12 months before asking you to re-authorize sale or sharing.</p>\n            \n              <h3>Your CCPA/CPRA rights and how to exercise them</h3>\n              <p><strong>Right to know and portability.</strong> You may request that we disclose:</p>\n              <ul>\n                <li>the categories of personal information we collected about you;</li>\n                <li>the sources of that information;</li>\n                <li>the purposes for which we use it;</li>\n                <li>the categories of third parties to whom we disclose it; and</li>\n                <li>the specific pieces of personal information we collected about you.</li>\n              </ul>\n              <p>You also have the right to know what personal information we sold or shared and to whom, including two separate lists showing: (i) the categories sold or shared and the categories of third parties; and (ii) the categories disclosed for a business purpose and the categories of recipients. Disclosures generally cover the preceding 12 months (and beyond January 1, 2022 when technically feasible and not disproportionately burdensome). Electronic disclosures will be provided in a portable, readily usable format where feasible.</p>\n            \n              <p><strong>Right to delete.</strong> You may request deletion of your personal information, subject to legal exceptions (e.g., security, fraud prevention, debugging, or to fulfill transactions).</p>\n              <p><strong>Right to correct.</strong> You may request correction of inaccurate personal information we maintain about you.</p>\n              <p><strong>Right to opt out of sale/sharing and to limit use of sensitive personal information.</strong> You may opt out at any time. (We do not collect sensitive personal information.)</p>\n              <p><strong>Non-discrimination.</strong> We will not discriminate against you for exercising your rights. If certain information is necessary to provide a service, we may be unable to complete a transaction without it. Where permitted, we may offer promotions or financial incentives reasonably related to the value of your information (e.g., bona fide loyalty or rewards programs).</p>\n            \n              <h4>How to submit a request</h4>\n              <ul>\n                <li>Contact us using the details at the start of this document.</li>\n                <li>Your request must provide sufficient information to verify your identity and describe the request with enough detail for us to respond.</li>\n                <li>If we cannot verify your identity, we will not respond to the request.</li>\n                <li>You do not need an account to make a request. Any information collected to verify your request will be used only for verification and retained no longer than necessary.</li>\n                <li>Authorized agents registered with the California Secretary of State may act on your behalf. Adults may make requests for their minor children.</li>\n                <li>You may submit up to two requests within a 12-month period.</li>\n              </ul>\n            \n              <h4>Timing and our response</h4>\n              <ul>\n                <li>We will confirm receipt within 10 days and explain our process.</li>\n                <li>We will respond within 45 days. If more time is needed (up to a total of 90 days), we will tell you why and for how long.</li>\n                <li>Our response will cover the preceding 12 months; for data collected on or after January 1, 2022, you may request disclosures beyond 12 months unless impossible or disproportionately burdensome.</li>\n                <li>If we deny your request, we will explain why.</li>\n                <li>We do not charge a fee unless a request is manifestly unfounded or excessive; in such cases we may charge a reasonable fee or refuse to act and will explain our decision.</li>\n              </ul>\n            </section>\n            \n            <section id=\"virginia\">\n              <h2>Further information for Virginia residents</h2>\n              <p>This section supplements the policy for residents of the Commonwealth of Virginia under the Virginia Consumer Data Protection Act (\u201cVCDPA\u201d). \u201cPersonal data\u201d has the meaning given in the VCDPA.</p>\n            \n              <h3>Categories processed & purposes</h3>\n              <p>See <em>Detailed information on the processing of personal data</em> and <em>The purposes of processing</em> for full details. We will not process your data for incompatible purposes without your consent. You may grant or withdraw consent at any time using the contact details provided.</p>\n            \n              <h3>Types of personal data we collect</h3>\n              <ul>\n                <li>Identifiers and internet information</li>\n                <li>We do not collect sensitive data.</li>\n                <li>We will not add new categories without notice.</li>\n              </ul>\n            \n              <h3>Sharing with third parties</h3>\n              <p>We share personal data with third parties listed in <em>Detailed information on the processing of personal data</em>, grouped by processing purpose. \u201cThird party\u201d has the meaning in the VCDPA.</p>\n            \n              <h3>Sale</h3>\n              <p>\u201cSale\u201d means exchanging personal data for monetary consideration with a third party. Disclosures to processors acting on our behalf are not sales. Other VCDPA exceptions may apply. Our uses may, in some cases, be considered a sale under the VCDPA.</p>\n            \n              <h3>Opt-out of sale</h3>\n              <p>You may opt out of the sale of your personal data at any time by contacting us using the details provided. We will use any information collected with your opt-out solely to comply with the request.</p>\n            \n              <h3>Targeted advertising</h3>\n              <p>We do not currently process personal data for targeted advertising. If we choose to do so, we will inform you in advance and honor your right to opt out.</p>\n            \n              <h3>Your VCDPA rights</h3>\n              <ul>\n                <li><strong>Access:</strong> confirm whether we process your personal data and access it.</li>\n                <li><strong>Correct:</strong> request correction of inaccurate personal data.</li>\n                <li><strong>Delete:</strong> request deletion of personal data.</li>\n                <li><strong>Portability:</strong> obtain your data in a portable, usable format where technically feasible.</li>\n                <li><strong>Opt out:</strong> of targeted advertising, sale of personal data, or profiling producing legal or similarly significant effects.</li>\n                <li><strong>Non-discrimination:</strong> we will not discriminate for exercising your rights. Where permitted, we may offer different prices or benefits related to bona fide loyalty or rewards programs.</li>\n              </ul>\n            \n              <h3>How to exercise your rights</h3>\n              <ul>\n                <li>Submit a request using the contact details provided at the start of this document.</li>\n                <li>We must verify your identity using commercially reasonable efforts; we may request additional information to authenticate you.</li>\n                <li>You do not need to create an account, though we may require you to use an existing account. Any data collected for authentication will be used only for that purpose and retained no longer than necessary.</li>\n                <li>Adults may submit requests for children under their parental authority.</li>\n              </ul>\n            \n              <h3>Timing and appeals</h3>\n              <ul>\n                <li>We will respond without undue delay and no later than 45 days; we may extend up to 90 days with notice.</li>\n                <li>If we deny your request, you may appeal using the contact details provided. We will respond in writing within 60 days with our decision and reasons. If denied, you may contact the Virginia Attorney General.</li>\n                <li>We do not charge a fee for up to two requests per year unless a request is manifestly unfounded, excessive, or repetitive.</li>\n              </ul>\n            </section>\n            \n            <section id=\"colorado\">\n              <h2>Further information for Colorado residents</h2>\n              <p>This section supplements the policy for Colorado residents under the Colorado Privacy Act (\u201cCPA\u201d). \u201cPersonal data\u201d has the meaning in the CPA.</p>\n            \n              <h3>Categories processed & purposes</h3>\n              <p>See <em>Detailed information on the processing of personal data</em> for full details. We will not process data for incompatible purposes without your consent; you may grant or withdraw consent at any time using the contact details provided.</p>\n            \n              <h3>Categories we collect</h3>\n              <ul>\n                <li>Identifiers and internet information</li>\n                <li>We do not collect sensitive data.</li>\n                <li>No new categories will be collected without notice.</li>\n              </ul>\n            \n              <h3>Sharing with third parties</h3>\n              <p>We share personal data with third parties listed in <em>Detailed information on the processing of personal data</em>, grouped by purpose. \u201cThird party\u201d has the meaning in the CPA.</p>\n            \n              <h3>Sale</h3>\n              <p>Our use of personal data may be considered a \u201csale\u201d under the CPA (exchange for monetary or other valuable consideration). Disclosures to processors are not sales; other CPA exceptions may apply.</p>\n            \n              <h3>Opt-out of sale</h3>\n              <p>You may opt out of the sale of your personal data at any time via the contact details at the start of this document or via the privacy choices link on this website. Information collected to process an opt-out is used solely for that purpose.</p>\n            \n              <h3>Targeted advertising</h3>\n              <p>We do not currently process personal data for targeted advertising. If we choose to do so, we will inform you and honor your right to opt out. \u201cTargeted advertising\u201d has the meaning in the CPA and does not include contextual ads, first-party ads, direct responses to your requests, or measurement/reporting alone.</p>\n            \n              <h3>Your CPA rights</h3>\n              <ul>\n                <li>Opt out of targeted advertising, sale of personal data, or profiling with legal or similarly significant effects.</li>\n                <li>Access personal data and confirm whether we process it.</li>\n                <li>Correct inaccurate personal data.</li>\n                <li>Request deletion of personal data.</li>\n                <li>Obtain a portable copy where technically feasible.</li>\n              </ul>\n              <p>We will not increase price or decrease availability solely because you exercise your rights. Where permitted, we may offer different prices or benefits related to bona fide loyalty or rewards programs.</p>\n            \n              <h3>How to exercise your rights</h3>\n              <ul>\n                <li>Submit a request using the contact details provided.</li>\n                <li>We must verify your identity and understand which right you wish to exercise; we may request additional information.</li>\n                <li>You do not need to create an account, though we may require use of an existing account. Authentication data will be used only for that purpose and retained no longer than necessary.</li>\n                <li>Adults may submit requests for children under their parental authority.</li>\n              </ul>\n            \n              <h3>Timing and appeals</h3>\n              <ul>\n                <li>We will respond within 45 days; we may extend up to 90 days with notice.</li>\n                <li>If we deny your request, you may appeal. We will respond within 45 days with reasons. If denied, you may contact the Colorado Attorney General.</li>\n                <li>No fee for up to two requests per year.</li>\n              </ul>\n            </section>\n            \n            <section id=\"connecticut\">\n              <h2>Further information for Connecticut residents</h2>\n              <p>This section supplements the policy for Connecticut residents under the Connecticut Data Privacy Act (\u201cCTDPA\u201d). \u201cPersonal data\u201d has the meaning in the CTDPA.</p>\n            \n              <h3>Categories processed & purposes</h3>\n              <p>See <em>Detailed information on the processing of personal data</em> and <em>The purposes of processing</em> for details. We will not process data for incompatible purposes without your consent; you may grant or withdraw consent at any time.</p>\n            \n              <h3>Categories we collect</h3>\n              <ul>\n                <li>Identifiers and internet information</li>\n                <li>We do not collect sensitive data.</li>\n                <li>No new categories will be collected without notice.</li>\n              </ul>\n            \n              <h3>Sharing with third parties</h3>\n              <p>We share personal data with third parties listed in <em>Detailed information on the processing of personal data</em>, grouped by purpose. \u201cThird party\u201d has the meaning in the CTDPA.</p>\n            \n              <h3>Sale</h3>\n              <p>Our use of personal data may be considered a \u201csale\u201d under the CTDPA (exchange for monetary or other valuable consideration). Disclosures to processors are not sales; other CTDPA exceptions may apply.</p>\n            \n              <h3>Opt-out of sale</h3>\n              <p>You may opt out at any time using the contact details provided or the privacy choices link on this website. Information used to process an opt-out is used only for that purpose.</p>\n            \n              <h3>Targeted advertising</h3>\n              <p>We do not currently process personal data for targeted advertising. If we choose to do so, we will inform you and honor your right to opt out. \u201cTargeted advertising\u201d has the meaning in the CTDPA and excludes contextual/first-party ads, direct responses, and measurement/reporting alone.</p>\n            \n              <h3>Your CTDPA rights</h3>\n              <ul>\n                <li>Access personal data and confirm whether we process it</li>\n                <li>Correct inaccurate personal data</li>\n                <li>Request deletion of personal data</li>\n                <li>Obtain a portable copy where technically feasible</li>\n                <li>Opt out of targeted advertising, sale of personal data, or profiling with legal or similarly significant effects</li>\n              </ul>\n              <p>We will not increase price or decrease availability solely because you exercise your rights. Where permitted, we may offer different prices or benefits related to bona fide loyalty or rewards programs.</p>\n            \n              <h3>How to exercise your rights</h3>\n              <ul>\n                <li>Submit a request using the contact details provided.</li>\n                <li>We must verify your identity and understand the right you wish to exercise; we may request additional information.</li>\n                <li>You do not need to create an account, though we may require use of an existing account. Authentication data will be used only for that purpose and retained no longer than necessary.</li>\n                <li>Adults may submit requests for children under their parental authority.</li>\n              </ul>\n            \n              <h3>Timing and appeals</h3>\n              <ul>\n                <li>We will respond within 45 days; we may extend up to 90 days with notice.</li>\n                <li>If we deny your request, you may appeal. We will respond within 45 days with reasons. If denied, you may contact the Connecticut Attorney General.</li>\n                <li>No fee for up to one request per year.</li>\n              </ul>\n            </section>\n            \n            <section id=\"utah\">\n              <h2>Further information for Utah residents</h2>\n              <p>This section supplements the policy for Utah residents under the Utah Consumer Privacy Act (\u201cUCPA\u201d). \u201cPersonal data\u201d has the meaning in the UCPA.</p>\n            \n              <h3>Categories processed & purposes</h3>\n              <p>See <em>Detailed information on the processing of personal data</em> for details.</p>\n            \n              <h3>Categories we collect</h3>\n              <ul>\n                <li>Identifiers and internet information</li>\n                <li>We do not collect sensitive data.</li>\n                <li>No new categories will be collected without notice.</li>\n              </ul>\n            \n              <h3>Sharing with third parties</h3>\n              <p>We share personal data with third parties listed in <em>Detailed information on the processing of personal data</em>, grouped by purpose. \u201cThird party\u201d has the meaning in the UCPA.</p>\n            \n              <h3>Sale</h3>\n              <p>Our use of personal data may be considered a \u201csale\u201d under the UCPA (exchange for monetary or other valuable consideration). Disclosures to processors are not sales; other UCPA exceptions may apply.</p>\n            \n              <h3>Opt-out of sale / targeted advertising</h3>\n              <p>You may opt out of the sale of personal data and targeted advertising at any time using the contact details at the start of this document or the privacy choices link on this website. Information used to process an opt-out is used only for that purpose.</p>\n              <p>We do not currently process personal data for targeted advertising. If we choose to do so, we will inform you and honor your right to opt out. \u201cTargeted advertising\u201d has the meaning in the UCPA.</p>\n            \n              <h3>Your UCPA rights</h3>\n              <ul>\n                <li>Access personal data and confirm whether we process it</li>\n                <li>Request deletion of personal data</li>\n                <li>Obtain a portable copy where technically feasible</li>\n                <li>Opt out of targeted advertising or sale of personal data</li>\n              </ul>\n              <p>We will not increase price or decrease availability solely because you exercise your rights. Where permitted, we may offer different prices or benefits related to bona fide loyalty or rewards programs.</p>\n            \n              <h3>How to exercise your rights</h3>\n              <ul>\n                <li>Submit a request using the contact details provided.</li>\n                <li>We must verify your identity and the right you wish to exercise; we may request additional information. We may retain your email address to respond to your request.</li>\n                <li>Adults may submit requests for children under their parental authority.</li>\n              </ul>\n            \n              <h3>Timing</h3>\n              <ul>\n                <li>We will respond within 45 days; we may extend up to 90 days with notice.</li>\n                <li>If we deny your request, we will explain why.</li>\n                <li>No fee for up to one request per year.</li>\n              </ul>\n            </section>\n            \n            <section id=\"about-this-document\">\n              <h2>Information about this document</h2>\n            </section>\n            \n            <section id=\"additional-info\">\n              <h2>Additional information about data collection and processing</h2>\n              <p><strong>Legal action.</strong> We may use personal data to protect our rights in court or before authorities arising from misuse of the website or related services. We may be required to disclose personal data upon lawful request by public authorities.</p>\n              <p><strong>Additional information.</strong> We may provide further contextual notices about specific services or processing upon request.</p>\n              <p><strong>System logs and maintenance.</strong> For operation and maintenance, this website and third-party services may collect system logs or other personal data (e.g., IP address).</p>\n              <p><strong>Information not contained here.</strong> You may request more details about collection or processing at any time using the contact information at the start of this document.</p>\n              <p><strong>Changes to this policy.</strong> We may update this policy by posting changes on this page and, where feasible, within the website or via available contact details. Please check the \u201cLast updated\u201d date. If changes affect processing based on your consent, we will seek new consent where required.</p>\n            </section>\n            \n            <section id=\"definitions\">\n              <h2>Definitions and legal references</h2>\n              <p><strong>Personal data (or \u201cdata\u201d):</strong> Information that identifies or can be used to identify a natural person, directly or indirectly (e.g., name, ID number).</p>\n              <p><strong>Usage data:</strong> Information collected automatically by this website or third-party services (e.g., IP address, browser, OS, request time/method, response status, visit duration, pages visited, device details).</p>\n              <p><strong>This website:</strong> The means by which personal data is collected and processed.</p>\n              <p><strong>Service:</strong> The service provided by this website as described in the Terms of Service and on this site.</p>\n              <p><strong>European Union (EU):</strong> References include EU Member States and, unless stated otherwise, the European Economic Area.</p>\n              <p><strong>Cookie:</strong> A tracker consisting of small data stored in your browser.</p>\n              <p><strong>Tracker:</strong> Any technology (e.g., cookies, identifiers, web beacons, embedded scripts, e-tags, fingerprinting) that enables tracking or access/storage of information on your device.</p>\n              <p><strong>Legal information:</strong> This privacy statement is prepared based on multiple laws. It applies solely to this website unless stated otherwise.</p>\n            </section>\n          </article>\n        </main></body></html>", "terms-of-service": "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Terms of Service - Route 66 Hemp</title><style>body{max-width:900px;margin:auto;padding:28px;font:17px/1.65 system-ui;color:#183429}a{color:#145c42}table{display:block;overflow:auto}h1{line-height:1.2}</style></head><body><a href=\"/\">Back to closure notice</a><p>Archived policy retained for reference following the store closure. The closure page does not load the former site's analytics scripts.</p><main>\n            <h1 class=\"mb-4 text-3xl font-bold\">\n                Route 66 Hemp Terms of Service\n            </h1>\n            <p class=\"mb-4\">\n                PLEASE READ THESE TERMS OF SERVICE (\"TERMS\", \"AGREEMENT\")\n                CAREFULLY. BY ACCESSING OR USING OUR WEBSITE, YOU AGREE TO BE\n                BOUND BY THESE TERMS.\n            </p>\n            <h2 class=\"mb-2 mt-6 text-2xl font-semibold\">Privacy</h2>\n            <p class=\"mb-4\">\n                Our Privacy Policy describes how we collect, use, and share your information. By\n                using this site, you consent to our Privacy Policy.\n            </p>\n            <h2 class=\"mb-2 mt-6 text-2xl font-semibold\">Restrictions</h2>\n            <p class=\"mb-4\">\n                The information on this site is for your personal,\n                non-commercial use. You may not reproduce, distribute, or\n                otherwise exploit any content without our written permission.\n                You agree not to use any automated means to access the site or\n                interfere with its operation.\n            </p>\n            <h2 class=\"mb-2 mt-6 text-2xl font-semibold\">Eligibility</h2>\n            <p class=\"mb-4\">\n                This site is intended only for users who are twenty-one (21)\n                years of age or older. By using the site, you represent that you\n                meet this requirement.\n            </p>\n            <h2 class=\"mb-2 mt-6 text-2xl font-semibold\">\n                Disclaimer of Warranty\n            </h2>\n            <p class=\"mb-4\">\n                THIS SITE AND ALL INFORMATION PROVIDED IS OFFERED \"AS IS\"\n                WITHOUT WARRANTY OF ANY KIND. ROUTE 66 HEMP DISCLAIMS ALL\n                WARRANTIES, EXPRESS OR IMPLIED, INCLUDING MERCHANTABILITY AND\n                FITNESS FOR A PARTICULAR PURPOSE.\n            </p>\n            <h2 class=\"mb-2 mt-6 text-2xl font-semibold\">\n                Limitation of Liability\n            </h2>\n            <p class=\"mb-4\">\n                TO THE EXTENT PERMITTED BY LAW, ROUTE 66 HEMP SHALL NOT BE\n                LIABLE FOR ANY DAMAGES ARISING OUT OF OR RELATED TO YOUR USE OF\n                THIS SITE.\n            </p>\n            <h2 class=\"mb-2 mt-6 text-2xl font-semibold\">Indemnification</h2>\n            <p class=\"mb-4\">\n                You agree to indemnify and hold Route 66 Hemp harmless from any\n                claims arising out of your use of the site or violation of these\n                Terms.\n            </p>\n            <h2 class=\"mb-2 mt-6 text-2xl font-semibold\">\n                Governing Law; Dispute Resolution\n            </h2>\n            <p class=\"mb-4\">\n                These Terms are governed by the laws of the State of Missouri.\n                ANY DISPUTE SHALL BE RESOLVED BY CONFIDENTIAL ARBITRATION IN\n                PULASKI COUNTY, MISSOURI, ON AN INDIVIDUAL BASIS.\n            </p>\n            <p class=\"mt-8\">\n                If you have questions about these Terms, please contact us at\n                <a href=\"mailto:route66hemp@gmail.com\" class=\"text-blue-600 underline dark:text-blue-400\" >route66hemp@gmail.com</a>.\n            </p>\n        </main></body></html>", "cookie-policy": "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Cookie Policy - Route 66 Hemp</title><style>body{max-width:900px;margin:auto;padding:28px;font:17px/1.65 system-ui;color:#183429}a{color:#145c42}table{display:block;overflow:auto}h1{line-height:1.2}</style></head><body><a href=\"/\">Back to closure notice</a><p>Archived policy retained for reference following the store closure. The closure page does not load the former site's analytics scripts.</p><main>\n            <h1><strong>Cookie Policy of [<a href=\"https://www.route66hemp.com\">www.route66hemp.com</a>]</strong></h1>\n            <p>Last updated: August 19, 2025</p>\n            <p>We are Route 66 Hemp LLC. This cookie policy outlines how we collect, use, and manage cookies, and we outline your rights and choices regarding cookie usage.</p>\n            <p>You can contact us at route66hemp@gmail.com.</p>\n            <hr>\n            <h2>Table of contents</h2>\n            <ul>\n            <li>Introduction</li>\n            <li>Contact information</li>\n            <li>Activities strictly necessary for the operation of this website and delivery of the service</li>\n            <li>How to manage preferences and provide or withdraw consent</li>\n            <li>Definitions and legal references</li>\n            </ul>\n            <hr>\n            <h2><strong>Introduction</strong></h2>\n            <p><strong>What is this policy about?</strong><br>\n            This document tells you about tracking technologies (\u201ctrackers\u201d) that help this website achieve the purposes outlined in this document.</p>\n            <p><strong>What are trackers?</strong><br>\n            For simplicity, all such technologies are defined as \"trackers\" within this document \u2013 unless there is a reason to differentiate. For example, while cookies can be used on both web and mobile browsers, it would be inaccurate to talk about cookies in the context of mobile apps as they are a browser-based tracker. For this reason, within this document, the term cookies is only used where it is specifically meant to indicate that particular type of tracker.</p>\n            <p>Some of the purposes for which trackers are used may also require your consent. Whenever consent is given, it can be freely withdrawn at any time following the instructions provided in this document.</p>\n            <p>This website uses trackers managed directly by us (so-called \u201cfirst-party\u201d trackers) and trackers that enable services provided by a third-party (so-called \u201cthird-party\u201d trackers). Unless otherwise specified within this document, third-party providers may access the trackers managed by them.</p>\n            <p>The validity and expiration periods of cookies and other similar trackers may vary depending on the lifetime set by us or the relevant provider. Some of them expire upon termination of your browsing session. In addition to what\u2019s specified in the descriptions within each of the categories below, you may find more precise and updated information regarding lifetime specification as well as any other relevant information \u2014 such as the presence of other trackers\u2014 in the linked privacy policies of the respective third-party providers or by contacting us.</p>\n            <hr>\n            <h2>Contact Information</h2>\n            <p>Since the use of third-party trackers through this website cannot be fully controlled by us, any specific references to third-party trackers are to be considered indicative. In order to obtain complete information, you are kindly requested to consult the privacy policies of the respective third-party services listed in this document.</p>\n            <p>Given the objective complexity surrounding tracking technologies, you are encouraged to contact us should you wish to receive any further information on the use of such technologies by this website.</p>\n            <p><strong>Address:</strong><br>\n            14076 State Hwy Z<br>\n            St Robert, MO 65584<br>\n            United States</p>\n            <p><strong>Email:</strong> route66hemp@gmail.com</p>\n            <p><strong>Phone:</strong> (573) 677-6418</p>\n            <hr>\n            <h2><strong>Activities strictly necessary for the operation of this website and delivery of the service</strong></h2>\n            <p>This website uses so-called \u201ctechnical\u201d cookies and other similar trackers to carry out activities that are strictly necessary for the operation or delivery of the service.</p>\n            <h3><strong>Other activities involving the use of trackers</strong></h3>\n            <h3><strong>Experience</strong></h3>\n            <p>This website uses trackers to improve the quality of the user experience and enable interactions with external content, networks and platforms.</p>\n            <p><strong>Displaying content from external platforms</strong><br>\n            This type of service allows you to view content hosted on external platforms directly from the pages of this website and interact with them. Such services are often referred to as widgets, which are small elements placed on a website or app. They provide specific information or perform a particular function and often allow for user interaction. This type of service might still collect web traffic data for the pages where the service is installed, even when you do not use it.</p>\n            <p><strong>Google Fonts (Google LLC)</strong><br>\n            Google Fonts is a typeface visualization service provided by Google LLC that allows this website to incorporate content of this kind on its pages.</p>\n            <p>To understand Google's use of data, consult Google's <a href=\"https://policies.google.com/technologies/partner-sites\">partner policy</a> and their <a href=\"https://business.safety.google/privacy/\">Business data page</a>.</p>\n            <p><strong>Personal data processed:</strong> Trackers; Usage data <br>\n            <strong>Place of processing:</strong> United States<br>\n            <strong>Privacy policy:</strong><a href=\"https://business.safety.google/privacy/\">https://business.safety.google/privacy/</a><br>\n            <strong>Opt-out link:</strong><a href=\"https://tools.google.com/dlpage/gaoptout\">https://tools.google.com/dlpage/gaoptout</a></p>\n            <h3><strong>Measurement</strong></h3>\n            <p>This website uses trackers to measure traffic and analyze user behavior to improve the service.</p>\n            <p><strong>Analytics</strong><br>\n            The services contained in this section enable us to monitor and analyze web traffic and can be used to keep track of user behavior.</p>\n            <p><strong>Google Analytics (Universal Analytics) (Google LLC)</strong><br>\n            Google Analytics (Universal Analytics) is a web analysis service provided by Google LLC (\u201cGoogle\u201d). Google utilizes the Data collected to track and examine the use of this website, to prepare reports on its activities and share them with other Google services. Google may use the Data collected to contextualize and personalize the ads of its own advertising network.</p>\n            <p>To understand Google's use of data, consult Google's <a href=\"https://policies.google.com/technologies/partner-sites\">partner policy</a> and their <a href=\"https://business.safety.google/privacy/\">Business data page</a>.</p>\n            <p><strong>Personal data processed:</strong> Trackers; Usage data <br>\n            <strong>Place of processing:</strong> United States<br>\n            <strong>Privacy policy:</strong><a href=\"https://business.safety.google/privacy/\">https://business.safety.google/privacy/</a><br>\n            <strong>Opt-out link:</strong><a href=\"https://tools.google.com/dlpage/gaoptout\">https://tools.google.com/dlpage/gaoptout</a></p>\n            <p><strong>Storage duration:</strong><br>\n            AMP_TOKEN: 1 hour<br>\n            _ga: 2 years<br>\n            _gac*: 3 months<br>\n            _gat: 1 minute<br>\n            _gid: 1 day</p>\n            <hr>\n            <h2><strong>How to manage preferences and provide or withdraw consent</strong></h2>\n            <p>There are various ways to manage tracker related preferences and to provide and withdraw consent, where relevant:</p>\n            <p>You can manage preferences related to trackers from directly within your own device settings, for example, by preventing the use or storage of trackers.</p>\n            <p>Additionally, whenever the use of trackers is based on consent, you can provide or withdraw such consent by setting your preferences within the cookie notice or by updating such preferences accordingly via the relevant consent-preferences privacy widget, if available.</p>\n            <p>It is also possible, via relevant browser or device features, to delete previously stored trackers, including those used to remember your initial consent preferences.</p>\n            <p>Other trackers in the browser\u2019s local memory may be cleared by deleting the browsing history.</p>\n            <p>With regard to any third-party trackers, you can manage your preferences via the related opt-out link (where provided), by using the means indicated in the third party's privacy policy, or by contacting the third party.</p>\n            <h3><strong>Locating tracker settings</strong></h3>\n            <p>You can, for example, find information about how to manage cookies in the most commonly used browsers at the following addresses:</p>\n            <ul>\n            <li><a href=\"https://support.google.com/chrome/answer/95647?hl=en&p=cpn_cookies\">Google Chrome</a></li>\n            <li><a href=\"https://support.mozilla.org/en-US/kb/enhanced-tracking-protection-firefox-desktop?redirectslug=enable-and-disable-cookies-website-preferences&redirectlocale=en-US\">Mozilla Firefox</a></li>\n            <li><a href=\"https://support.apple.com/en-za/guide/safari/sfri11471/mac\">Apple Safari</a></li>\n            <li><a href=\"https://support.microsoft.com/en-us/windows/manage-cookies-in-microsoft-edge-view-allow-block-delete-and-use-168dab11-0753-043d-7c16-ede5947fc64d\">Microsoft Internet Explorer</a></li>\n            <li><a href=\"https://support.microsoft.com/en-us/windows/manage-cookies-in-microsoft-edge-view-allow-block-delete-and-use-168dab11-0753-043d-7c16-ede5947fc64d\">Microsoft Edge</a></li>\n            <li><a href=\"https://support.brave.com/hc/en-us/articles/360022806212-How-do-I-use-Shields-while-browsing\">Brave</a></li>\n            <li><a href=\"https://help.opera.com/en/latest/web-preferences/#cookies\">Opera</a></li>\n            </ul>\n            <p>You may also manage certain categories of trackers used on mobile apps by opting out through relevant device settings such as the device advertising settings for mobile devices, or tracking settings in general (you may open the device settings and look for the relevant setting).</p>\n            <h3><strong>Consequences of denying the use of trackers</strong></h3>\n            <p>You are free to decide whether or not to allow the use of trackers. However, please note that trackers help this website to provide a better experience and advanced functionalities to you (in line with the purposes outlined in this document). Therefore, if you choose to block the use of trackers, we may be unable to provide related features.</p>\n            <hr>\n            <h2><strong>Information about this document</strong></h2>\n            <hr>\n            <h2><strong>Definitions and legal references</strong></h2>\n            <p><strong>Personal data (or data)</strong><br>\n            Any information that directly, indirectly, or in connection with other information \u2014 including a personal identification number\u2014 allows for the identification or identifiability of a natural person (in other words, you).</p>\n            <p><strong>Usage data</strong><br>\n            Usage data is information automatically collected through this website or third-party services, including your IP address, browser type, operating system, time and method of requests, response status, visit duration, page sequence, and device-specific details.</p>\n            <p><strong>This website</strong><br>\n            The means by which your personal data is collected and processed.</p>\n            <p><strong>Service</strong><br>\n            The service provided by this website as described in the Terms of Service and on this site.</p>\n            <p><strong>European Union (or EU)</strong><br>\n            Unless otherwise specified, all references made within this document to the European Union include all current member states to the European Union and the European Economic Area.</p>\n            <p><strong>Cookie</strong><br>\n            Cookies are trackers consisting of small sets of data stored in your browser.</p>\n            <p><strong>Tracker</strong><br>\n            Tracker indicates any technology - e.g. cookies, unique identifiers, web beacons, embedded scripts, e-tags and fingerprinting - that enables the tracking of you, for example by accessing or storing information on your device.</p>\n            <p><strong>Legal information</strong><br>\n            This privacy statement has been prepared based on provisions of multiple legislations. This privacy policy relates solely to this website, if not stated otherwise within this document.</p>\n        </main></body></html>"}
